\begin{lemma}\label{lem:Martingale.integral_mul_increment_eq_zero_of_stronglyMeasurable}
  \uses{def:Martingale}
  \lean{MeasureTheory.Martingale.integral_mul_increment_eq_zero_of_stronglyMeasurable}
